#include <bits/stdc++.h>
using namespace std;using I=long long;using G=vector<int>;using P=array<I,7>;
void need(bool q,string s){if(!q)throw runtime_error(s);}
void valid(G a){int n=a.size();for(int i=0;i<n;i++){need(a[i]>=0&&a[i]<(1<<n)&&!(a[i]>>i&1),"row");for(int j=0;j<i;j++)need(((a[i]>>j&1)+(a[j]>>i&1))==1,"pair");}}
P count(G a,int root=0){valid(a);int n=a.size(),N=1<<n,F=N-1;vector<I>en(N*n),st(N*n),H(N);H[0]=1;for(int i=0;i<n;i++)en[(1<<i)*n+i]=st[(1<<i)*n+i]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++)if(S>>v&1){int A=S^(1<<v);for(int w=0;w<n;w++)if(A>>w&1){if(a[w]>>v&1)en[S*n+v]+=en[A*n+w];else st[S*n+v]+=st[A*n+w];}H[S]+=en[S*n+v];}I L=0,R=0,b=0;for(int S=0;S<N;S++){L+=en[S*n+root]*H[F^S];R+=st[S*n+root]*H[F^S];}int D=F^(1<<root),A=D;while(true){b+=H[A]*H[D^A];if(!A)break;A=(A-1)&D;}return {H[F],st[F*n+root],en[F*n+root],L,R,H[D],b};}
G relabel(G a,int root){vector<int>ord{root};for(int i=0;i<(int)a.size();i++)if(i!=root)ord.push_back(i);G b(a.size());for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)a.size();j++)if(a[ord[i]]>>ord[j]&1)b[i]|=1<<j;return b;}
G move(G a,char op){int n=a.size();for(auto&x:a)x|=1<<n;a.push_back(0);if(op!='O'){a[0]^=1<<n;a[n]=1;}if(op=='J')a=relabel(a,n);return a;}
P trans(P p,char op){auto[h,s,e,L,R,d,b]=p;if(op=='O')return {h,s,0,L,2*R,d,2*b};need(op=='Z',"unsupported transfer");return{h+R-e,s,d,L+b,2*R-d,d,2*b};}
I X(P p,int j){return p[0]+p[3]-p[1]+2*j;}
array<I,4> row(P p,int j){return {X(p,j),p[2],p[4]+p[6],p[5]};}
bool strong(G a){int n=a.size(),F=(1<<n)-1;for(int v=0;v<n;v++)a[v]|=1<<v;for(int k=0;k<n;k++)for(int v=0;v<n;v++)if(a[v]>>k&1)a[v]|=a[k];return all_of(a.begin(),a.end(),[&](int x){return x==F;});}
using U=uint64_t;
I capped_h(const G&a,I cap){int n=a.size(),N=1<<n,F=N-1;vector<I>d(N*n);for(int v=0;v<n;v++)d[(1<<v)*n+v]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++){I val=d[S*n+v];if(!val)continue;int todo=a[v]&~S;while(todo){int bit=todo&-todo;todo-=bit;int w=__builtin_ctz(bit);I&z=d[(S|bit)*n+w];z=min(cap+1,z+val);}}I h=0;for(int v=0;v<n;v++)h=min(cap+1,h+d[F*n+v]);return h;}
U canonical(const G&a){int n=a.size();map<int,vector<int>>cells;for(int i=0;i<n;i++)cells[__builtin_popcount((unsigned)a[i])].push_back(i);vector<vector<int>>parts;for(auto&[d,p]:cells)parts.push_back(p);vector<int>ord;U best=~U(0);function<void(int)>rec=[&](int g){if(g==(int)parts.size()){U code=0;int bit=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,bit++)if(a[ord[i]]>>ord[j]&1)code|=U(1)<<bit;best=min(best,code);return;}auto p=parts[g];do{for(int v:p)ord.push_back(v);rec(g+1);ord.resize(ord.size()-p.size());}while(next_permutation(p.begin(),p.end()));};rec(0);return best;}
G decode(U code,int n){G a(n);int b=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,b++)if(code>>b&1)a[i]|=1<<j;else a[j]|=1<<i;return a;}
G delroot(G a,int skip,int root){vector<int>ord{root};for(int i=0;i<(int)a.size();i++)if(i!=root&&i!=skip)ord.push_back(i);G out(ord.size());for(int i=0;i<(int)ord.size();i++)for(int j=0;j<(int)ord.size();j++)if(a[ord[i]]>>ord[j]&1)out[i]|=1<<j;return out;}
int main(int argc,char**argv){I bound=argc>1?stoll(argv[1]):137;int scap=argc>2?stoi(argv[2]):26;need(bound>=3&&bound<=100000,"bound range");int ncap=3;for(int n=3;;n++){I val;if(n%3==0){val=3;for(int k=0;k<(n-3)/3;k++)val*=5;}else if(n%3==1){val=1;for(int k=0;k<(n-1)/3;k++)val*=5;}else{val=9;for(int k=0;k<(n-5)/3;k++)val*=5;}if(val>bound)break;ncap=n;}
 // A uint64_t upper-triangle code supports at most 11 vertices (55 bits).
 need(ncap<=11,"canonical uint64 code requires strong order at most 11");
 need(scap>=1&&scap<=bound,"s cap must be positive and at most the B bound");
 vector<map<U,I>>banks(ncap+1);G tri{2,4,1};banks[3][canonical(tri)]=3;vector<I>trials(ncap+1),accepted(ncap+1);ofstream bank("BANK.tsv");set<pair<I,I>> strong_profiles;map<pair<I,I>,G>witness;set<I>factorcounts;int edgesources=0;
 for(int n=3;n<=ncap;n++){if(n>3){for(auto[code,h]:banks[n-1]){G a=decode(code,n-1);for(int mask=1;mask<(1<<(n-1))-1;mask++){trials[n]++;G b=a;for(int i=0;i<n-1;i++)if(mask>>i&1)b[i]|=1<<(n-1);b.push_back(((1<<(n-1))-1)^mask);I hh=capped_h(b,bound);if(hh>bound)continue;accepted[n]++;U key=canonical(b);auto[it,ok]=banks[n].emplace(key,hh);need(ok||it->second==hh,"canonical collision count");}}}
 cerr<<"n="<<n<<" trials="<<trials[n]<<" accepted_extensions="<<accepted[n]<<" classes="<<banks[n].size()<<'\n';
 for(auto[code,h]:banks[n]){G a=decode(code,n);need(strong(a),"bank strong");need(canonical(a)==code,"canonical idempotent");bank<<n<<' '<<h<<' '<<code;for(int row:a)bank<<' '<<row;bank<<'\n';if(h<=scap)factorcounts.insert(h);for(int skip=0;skip<n;skip++){int incoming=((1<<n)-1)^a[skip]^(1<<skip);if(__builtin_popcount((unsigned)incoming)!=1)continue;int root=__builtin_ctz((unsigned)incoming);G c=delroot(a,skip,root);if(!strong(c))continue;P p=count(c);need(X(p,0)==h,"edge source identity");if(p[1]<=scap){strong_profiles.insert({h,p[1]});witness.try_emplace({h,p[1]},c);edgesources++;}}}
 }
 vector<bool>tail(scap+1);tail[1]=true;for(int q=2;q<=scap;q++)for(I c:factorcounts)if(q%c==0&&tail[q/c])tail[q]=true;set<pair<I,I>> allprofiles;for(int q=1;q<=scap;q++)if(tail[q]){if(q<=bound)allprofiles.insert({q,q});for(auto[B,s]:strong_profiles)if(q*B<=bound&&q*s<=scap)allprofiles.insert({q*B,q*s});}
 ofstream sp("STRONG_PROFILES.tsv"),ap("ALL_PROFILES.tsv");for(auto[B,s]:strong_profiles){G a=witness[{B,s}];sp<<B<<' '<<s<<' '<<a.size();for(int row:a)sp<<' '<<row;sp<<'\n';}for(auto[B,s]:allprofiles)ap<<B<<' '<<s<<'\n';
 cout<<"{\n  \"status\": \"COMPLETE_WITH_CITED_BUSCH_BOUND\",\n  \"B_bound\": "<<bound<<",\n  \"s_cap\": "<<scap<<",\n  \"strong_extension_order_cap\": "<<ncap<<",\n  \"strong_classes_by_order\": {";for(int n=3;n<=ncap;n++){if(n>3)cout<<", ";cout<<'"'<<n<<"\": "<<banks[n].size();}cout<<"},\n  \"strong_profile_count\": "<<strong_profiles.size()<<",\n  \"all_profile_count\": "<<allprofiles.size()<<",\n  \"rooted_edge_source_occurrences\": "<<edgesources<<",\n  \"tail_counts\": [";bool comma=false;for(int q=1;q<=scap;q++)if(tail[q]){if(comma)cout<<", ";comma=true;cout<<q;}cout<<"],\n  \"base137_successful_shifts\": [";for(int r=1;r<=2;r++){if(r>1)cout<<", ";cout<<'[';bool c=false;for(int j=0;j<=8;j++)if(allprofiles.count({137-2*j,r+3*j})){if(c)cout<<", ";c=true;cout<<j;}cout<<']';}cout<<"],\n  \"unit_start_B137\": "<<(allprofiles.count({137,1})?"true":"false")<<",\n  \"F_8_137_all_base_scope\": \"OPEN\"\n}\n";
}
